import { sql } from 'drizzle-orm';
import {
  bigint,
  check,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
} from 'drizzle-orm/pg-core';
import { user } from './auth.js';

// 03_DATA_MODEL.md §3. UUID v7 primary keys are generated by the application (@app/kernel uuidV7);
// every jsonb column is validated by a Zod schema on write and on read.
const tz = (name: string) => timestamp(name, { withTimezone: true });
const createdAt = () => tz('created_at').notNull().defaultNow();

export const memberRole = pgEnum('member_role', ['owner', 'editor', 'viewer']);
export const projectStatus = pgEnum('project_status', [
  'draft',
  'analyzing',
  'ready',
  'failed',
  'archived',
]);
export const actorKind = pgEnum('actor_kind', ['user', 'ai', 'system']);
export const assetKind = pgEnum('asset_kind', [
  'logo_original',
  'logo_sanitized',
  'logo_variant',
  'brief_doc',
  'mockup_render',
  'export_pdf',
  'export_zip',
]);
export const assetStatus = pgEnum('asset_status', ['pending', 'quarantined', 'clean', 'rejected']);
export const exportKind = pgEnum('export_kind', ['pdf', 'zip']);
export const exportStatus = pgEnum('export_status', ['pending', 'running', 'done', 'failed']);

export const workspaces = pgTable('workspaces', {
  id: uuid('id').primaryKey(),
  name: text('name').notNull(),
  ownerUserId: text('owner_user_id')
    .notNull()
    .references(() => user.id),
  createdAt: createdAt(),
  deletedAt: tz('deleted_at'),
});

export const workspaceMembers = pgTable(
  'workspace_members',
  {
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id),
    userId: text('user_id')
      .notNull()
      .references(() => user.id),
    role: memberRole('role').notNull(),
  },
  (table) => [primaryKey({ columns: [table.workspaceId, table.userId] })],
);

export const guestSessions = pgTable('guest_sessions', {
  id: uuid('id').primaryKey(),
  tokenHash: text('token_hash').notNull().unique(), // SHA-256 of the cookie token (SEC-10)
  createdAt: createdAt(),
  expiresAt: tz('expires_at').notNull(),
  claimedByUserId: text('claimed_by_user_id').references(() => user.id),
});

export const projects = pgTable(
  'projects',
  {
    id: uuid('id').primaryKey(),
    workspaceId: uuid('workspace_id').references(() => workspaces.id),
    guestSessionId: uuid('guest_session_id').references(() => guestSessions.id),
    title: text('title').notNull(),
    industryLabel: text('industry_label'),
    sceneCategory: text('scene_category'),
    language: text('language').notNull().default('fr'),
    briefText: text('brief_text'),
    status: projectStatus('status').notNull().default('draft'),
    createdAt: createdAt(),
    updatedAt: tz('updated_at').notNull().defaultNow(),
    deletedAt: tz('deleted_at'),
  },
  (table) => [
    // Exactly one owner: a workspace or a guest session.
    check(
      'projects_single_owner',
      sql`(${table.workspaceId} IS NOT NULL) <> (${table.guestSessionId} IS NOT NULL)`,
    ),
    check('projects_brief_length', sql`char_length(${table.briefText}) <= 8000`),
  ],
);

export const documents = pgTable('documents', {
  projectId: uuid('project_id')
    .primaryKey()
    .references(() => projects.id),
  schemaVersion: integer('schema_version').notNull(),
  body: jsonb('body').notNull(),
  seq: bigint('seq', { mode: 'number' }).notNull(),
  updatedAt: tz('updated_at').notNull().defaultNow(),
});

export const revisions = pgTable(
  'revisions',
  {
    id: uuid('id').primaryKey(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id),
    seq: bigint('seq', { mode: 'number' }).notNull(),
    actor: actorKind('actor').notNull(),
    command: jsonb('command').notNull(),
    inverse: jsonb('inverse').notNull(), // always carries `expect` (ADR-018)
    undoOf: bigint('undo_of', { mode: 'number' }),
    redoOf: bigint('redo_of', { mode: 'number' }),
    snapshot: jsonb('snapshot'),
    createdAt: createdAt(),
  },
  (table) => [
    unique('revisions_project_seq').on(table.projectId, table.seq),
    check('revisions_undo_xor_redo', sql`${table.undoOf} IS NULL OR ${table.redoOf} IS NULL`),
  ],
);

export const assets = pgTable(
  'assets',
  {
    id: uuid('id').primaryKey(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id),
    kind: assetKind('kind').notNull(),
    status: assetStatus('status').notNull().default('pending'),
    storageKey: text('storage_key').notNull().unique(),
    sha256: text('sha256'),
    mime: text('mime'), // from the bytes (SEC-12), never as announced
    bytes: bigint('bytes', { mode: 'number' }),
    width: integer('width'),
    height: integer('height'),
    rejectReason: text('reject_reason'),
    meta: jsonb('meta').notNull().default({}),
    createdAt: createdAt(),
    deletedAt: tz('deleted_at'),
  },
  (table) => [index('assets_project_kind').on(table.projectId, table.kind)],
);

// SSE log (04_API_CONTRACTS.md §5, decision T-019): NOTIFY keeps nothing, so a reconnecting client replays
// the rows after its Last-Event-ID. The identity column is the stream's increasing event id. Short-lived:
// purged by the hourly job.
export const projectEvents = pgTable(
  'project_events',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedAlwaysAsIdentity(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id),
    type: text('type').notNull(),
    data: jsonb('data').notNull(),
    createdAt: createdAt(),
  },
  (table) => [index('project_events_project_id').on(table.projectId, table.id)],
);

export const chatMessages = pgTable(
  'chat_messages',
  {
    id: uuid('id').primaryKey(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id),
    role: text('role').notNull(),
    content: text('content').notNull(),
    targetPageId: text('target_page_id'),
    revisionSeqs: bigint('revision_seqs', { mode: 'number' })
      .array()
      .notNull()
      .default(sql`'{}'`),
    createdAt: createdAt(),
  },
  (table) => [
    check('chat_messages_role', sql`${table.role} IN ('user', 'assistant')`),
    index('chat_project_created').on(table.projectId, table.createdAt),
  ],
);

export const exports = pgTable('exports', {
  id: uuid('id').primaryKey(),
  projectId: uuid('project_id')
    .notNull()
    .references(() => projects.id),
  kind: exportKind('kind').notNull(),
  status: exportStatus('status').notNull().default('pending'),
  assetId: uuid('asset_id').references(() => assets.id),
  errorCode: text('error_code'),
  attempts: integer('attempts').notNull().default(0),
  createdAt: createdAt(),
});

export const shareLinks = pgTable('share_links', {
  id: uuid('id').primaryKey(),
  projectId: uuid('project_id')
    .notNull()
    .references(() => projects.id),
  tokenHash: text('token_hash').notNull().unique(), // ≥ 128-bit token, stored hashed (SEC-09)
  expiresAt: tz('expires_at').notNull(),
  revokedAt: tz('revoked_at'),
  createdAt: createdAt(),
});

export const usageEvents = pgTable(
  'usage_events',
  {
    id: uuid('id').primaryKey(),
    userId: text('user_id').references(() => user.id),
    guestSessionId: uuid('guest_session_id').references(() => guestSessions.id),
    kind: text('kind').notNull(),
    model: text('model'),
    tokensIn: integer('tokens_in'),
    tokensOut: integer('tokens_out'),
    estCostMicroEur: bigint('est_cost_micro_eur', { mode: 'number' }),
    createdAt: createdAt(),
  },
  (table) => [index('usage_user_day').on(table.userId, table.createdAt)],
);

export const auditLog = pgTable('audit_log', {
  id: uuid('id').primaryKey(),
  actorRef: text('actor_ref').notNull(), // hashed identifier, never a direct one
  action: text('action').notNull(),
  subject: text('subject'),
  createdAt: createdAt(),
});
